{"tiddlers":{"$:/plugins/huwiki/shop/model.js":{"title":"$:/plugins/huwiki/shop/model.js","type":"application/javascript","module-type":"library","text":"/* Shop catalog adaptation. Original model/layouts: HUWiki Shop 0.1.2. */
"use strict";
var templates=require('$:/plugins/huwiki/shop/templates.js').items, original=require('$:/plugins/huwiki/shop/original.js');
function clean(v,n){return String(v==null?'':v).trim().slice(0,n);}
function https(v){v=clean(v,2000);if(!v)return '';var u;try{u=new URL(v);}catch(e){throw Error('https');}if(u.protocol!=='https:'||u.username||u.password)throw Error('https');return u.href;}
function image(v){v=clean(v,2000000);if(!v)return '';if(/^data:image\/(?:png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(v))return v;return https(v);}
function catalog(x){
 x=x||{};var d={title:clean(x.title,120),intro:clean(x.intro,1600),template:templates.some(t=>t.id===x.template)?x.template:'fri',layout:['gallery','list','poster'].includes(x.layout)?x.layout:'gallery',color:['forest','berry','ink','clay'].includes(x.color)?x.color:'clay',contact:clean(x.contact,240),delivery:clean(x.delivery,600),recipient:clean(x.recipient,120),phone:clean(x.phone,30),paymentLink:https(x.paymentLink),qrImage:image(x.qrImage),mode:['google','external','catalog'].includes(x.mode)?x.mode:'google',formUrl:'',items:[]};
 if(!d.title)throw Error('title');
 if(d.paymentLink&&!/^https:\/\/(?:[\w-]+\.)*(?:mobilepay\.dk|mobilepay\.fi|vippsmobilepay\.com)\//i.test(d.paymentLink))throw Error('payment');
 if(!Array.isArray(x.items)||!x.items.length||x.items.length>25)throw Error('items');
 d.items=x.items.map(function(v){var price=Number(String(v.price==null?0:v.price).replace(',','.'));if(!Number.isFinite(price)||price<0||price>100000)throw Error('price');var item={name:clean(v.name,100),variant:clean(v.variant,60),description:clean(v.description,500),status:clean(v.status,180),image:image(v.image),price:Math.round(price*100)/100};if(!item.name)throw Error('item');return item;});
 if(d.mode!=='catalog'&&x.formUrl){d.formUrl=https(x.formUrl);var url=new URL(d.formUrl);if(d.mode==='google'&&!(url.hostname==='forms.gle'&&url.pathname.length>1||url.hostname==='docs.google.com'&&/^\/forms\/(?:u\/\d+\/)?d\/(?:e\/)?[^/]+\/viewform$/.test(url.pathname)))throw Error('form');}
 return d;
}
function escape(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function site(input,lang,preview){
 var d=catalog(input),en=lang==='en',e=escape,t=(da,eng)=>en?eng:da;
 if(!preview&&d.mode!=='catalog'&&!d.formUrl)throw Error('form');
 var accent={forest:'#285542',berry:'#81354d',ink:'#253b55',clay:'#a64e31'}[d.color];
 var order=d.formUrl?'<a class="button" href="'+e(d.formUrl)+'" target="_blank" rel="noopener noreferrer">'+t('Bestil / tilmeld dig →','Order / register →')+'</a>':'<p>'+t(d.mode==='catalog'?'Kontakt os for at høre mere.':'Forhåndsvisning — formularlink mangler.',d.mode==='catalog'?'Contact us to find out more.':'Preview — form link not connected.')+'</p>';
 var html='<main class="shop-site '+d.layout+'" style="--accent:'+accent+'"><header><div><div class="eyebrow">'+t('Katalog · bestillinger','Catalog · orders')+'</div><h1>'+e(d.title)+'</h1><p>'+e(d.intro)+'</p>'+order+'</div><div class="stamp" aria-hidden="true">'+t('Vælg.<br>Send.','Choose.<br>Send.')+'</div></header><section class="grid">'+d.items.map((v,i)=>'<article class="item">'+(v.image?'<img src="'+e(v.image)+'" alt="'+e(v.name)+'" loading="lazy">':'<div class="art" aria-hidden="true">'+original.art(d.template,i)+'</div>')+'<div><small>'+e(v.variant)+'</small><h2>'+e(v.name)+'</h2></div><p>'+e(v.description)+'</p><div><p class="price">'+(v.price?(en?v.price.toFixed(2)+' DKK':v.price.toFixed(2).replace('.',',')+' kr.'):t(d.template==='forespoergsel'?'Pris aftales':'Uden fast pris',d.template==='forespoergsel'?'Price to be agreed':'No fixed price'))+'</p><p class="status">'+e(v.status)+'</p></div></article>').join('')+'</section><section><h2>'+t('Sådan foregår det','How it works')+'</h2><p>'+e(d.delivery||t('Send dit ønske. Vi bekræfter pris, antal og levering manuelt. Ingen automatisk reservation.','Send your request. We confirm price, quantity and delivery manually. No automatic reservations.'))+'</p>'+order+'</section>';
 if(d.phone||d.paymentLink||d.qrImage)html+='<section class="pay"><h2>'+t('Betaling','Payment')+'</h2><p>'+t('Modtager: ','Recipient: ')+e(d.recipient)+' '+e(d.phone)+'</p>'+(d.qrImage?'<img src="'+e(d.qrImage)+'" alt="'+t('Modtagerens betalingskode','Recipient payment code')+'">':'')+(d.paymentLink?'<p><a class="button" href="'+e(d.paymentLink)+'" target="_blank" rel="noopener noreferrer">'+t('Åbn MobilePay','Open MobilePay')+'</a></p>':'')+'<p>'+t('Betal først efter vores bekræftelse. Skriv dit navn og hvad betalingen gælder. Vi kontrollerer betalingen manuelt.','Pay after our confirmation. Include your name and what the payment covers. We check payment manually.')+'</p></section>';
 html+='<footer><p>'+e(d.contact)+'</p><small>'+t('Skabt med Shop Edition · TiddlyWiki Forge','Created with Shop Edition · TiddlyWiki Forge')+'</small></footer></main>';
 return {fragment:'<style>'+original.css()+'</style>'+html,html:'<!doctype html><html lang="'+(en?'en':'da')+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(d.title)+'</title><style>'+original.css()+'</style></head><body>'+html+'</body></html>'};
}
function fromTemplate(id,lang){var entry=templates.find(t=>t.id===id)||templates[0],v=entry[lang==='en'?'en':'da'];return Object.assign({template:entry.id,layout:entry.layout,color:entry.color,mode:'google',formUrl:'',contact:'',delivery:'',recipient:'',phone:'',paymentLink:'',qrImage:''},JSON.parse(JSON.stringify(v)));}
exports.catalog=catalog;exports.site=site;exports.fromTemplate=fromTemplate;exports.templates=templates;
"},"$:/plugins/huwiki/shop/guide.js":{"title":"$:/plugins/huwiki/shop/guide.js","type":"application/javascript","module-type":"library","text":"/* Each check is an owner's confirmation, not an automated Google/Funnel check. */
exports.steps=[
 {id:'catalog',title:['1. Din butik','1. Your shop'],intro:['Vælg en af de ni oprindelige startskabeloner. Ret navn, varer og tekster nedenfor. Gem din arbejdswiki med TiddlyWikis Gem-knap, så du kan fortsætte senere.','Choose one of the nine original templates. Edit the name, products and text below. Save your working wiki with TiddlyWiki’s Save button so you can return later.'],checks:[
  ['catalog-ready','Jeg har tilpasset varer, varianter og priser.','I have updated products, variants and prices.'],
  ['contact-ready','Kontakt og levering fortæller kunden, hvem der svarer og hvad der sker efter bestilling.','Contact and delivery explain who will reply and what happens after ordering.']
 ]},
 {id:'form',title:['2. Bestillingsformular','2. Order form'],intro:['Du logger selv ind hos Google i en anden fane. Shop beder ikke om adgang til din konto. Du kan også vælge en anden formular eller et katalog uden formular på trin 1.','Sign into Google yourself in another tab. Shop does not request access to your account. You can instead choose another form or a catalog without a form in step 1.'],checks:[
  ['google-account','Åbn Google Drev. Log ind med den konto, der skal eje butikken.','Open Google Drive. Sign in with the account that will own the shop.','https://drive.google.com/'],
  ['drive-folder','Vælg Ny → Ny mappe. Kald den fx “Min Shop”. Åbn mappen.','Choose New → New folder. Name it “My Shop”, for example. Open the folder.'],
  ['form-created','Vælg Ny → Google Analyse (Forms) → Tom formular. Skriv butikkens navn og en kort forklaring.','Choose New → Google Forms → Blank form. Enter your shop name and a short explanation.','https://support.google.com/docs/answer/6281888'],
  ['form-questions','Opret spørgsmålene fra listen nedenfor. Brug Kort svar til navn/kontakt, Rullemenu til antal og Afsnit til en valgfri besked. Indtast 0–10 som separate valgmuligheder. Du kan duplikere antalspørgsmålet til næste vare og rette navn og pris.','Create the questions listed below. Use Short answer for name/contact, Dropdown for quantities and Paragraph for an optional message. Enter 0–10 as separate options. Duplicate the quantity question for the next product, then change its name and price.'],
  ['form-settings','Under Indstillinger: slå “Begræns til ét svar” og “Vis oversigt over resultater” fra. Brug kundens indtastede kontaktfelt. Undgå filupload og verificeret mailindsamling, hvis kunden skal kunne svare uden Google-login.','In Settings: turn off “Limit to 1 response” and “View results summary”. Use the customer’s typed contact field. Avoid file uploads and verified email collection if customers should respond without signing into Google.'],
  ['form-confirmation','Skriv en bekræftelsestekst, fx “Tak! Vi kontakter dig og bekræfter pris og levering. Vent med betaling til da.”','Set a confirmation message, for example “Thank you! We will contact you to confirm price and delivery. Please wait for confirmation before paying.”'],
  ['form-published','Klik Offentliggør (Publish). Giv respondenter adgang med linket, hvis din konto tillader det. Kopiér respondentlinket — ikke redigeringsadressen — og indsæt det nedenfor.','Click Publish. Allow responder access to anyone with the link if your account permits it. Copy the responder link — not the editing address — and paste it below.','https://support.google.com/docs/answer/2839588']
 ]},
 {id:'sheet',title:['3. Dit private ordreark','3. Your private order sheet'],intro:['Forms kan selv oprette det regneark, der modtager svar. Det er her, du følger op på bestillinger. Kundesiden indeholder aldrig et link til dette ark.','Forms can create the spreadsheet that receives responses. This is where you follow up on orders. The customer site never includes a link to this sheet.'],checks:[
  ['sheet-created','I formularen: vælg Svar → Knyt til Sheets (regnearksikonet), eller ⋮ → Vælg destination for svar. Opret et nyt regneark, fx “Min Shop – bestillinger”.','In the form: choose Responses → Link to Sheets (spreadsheet icon), or ⋮ → Select destination for responses. Create a new spreadsheet, for example “My Shop – orders”.','https://support.google.com/docs/answer/2917686'],
  ['sheet-private','Åbn arket. Under Del behold Begrænset adgang. Del kun med de personer, der skal behandle ordrer. Kontrollér også formularens redaktører.','Open the sheet. Under Share keep access Restricted. Share only with people handling orders. Also check the form’s editors.'],
  ['order-tab','Opret en ekstra fane med + og kald den Ordrebog. Skriv kolonnerne fra eksemplet nedenfor i første række. Lad Forms-svarfanen være uændret.','Create an extra tab with + and name it Order book. Put the example columns below in the first row. Leave the Forms response tab unchanged.'],
  ['sheet-link','Gem arkets adresse i det private felt nedenfor. Den er kun en genvej for dig.','Save the sheet’s address in the private field below. It is only a shortcut for you.']
 ]},
 {id:'test-form',title:['4. Prøv som kunde','4. Try it as a customer'],intro:['Et korrekt link er ikke nok. Denne prøve viser, om dine kunder kan bestille, og om svarene lander det rigtige sted. Markér selv hvert resultat.','A valid link is not enough. This check shows whether customers can order and responses reach the right place. Confirm each result yourself.'],checks:[
  ['anonymous-form','Åbn respondentlinket i et privat/inkognito-vindue, hvor du ikke er logget ind. Formularen kan udfyldes uden adgangsanmodning. Googles tilbud om login for at gemme et udkast er valgfrit; kontrollér, at du kan sende uden login. Hvis kontoen blokerer offentlige svar, skal du ændre indstillingen eller vælge en anden formular.','Open the responder link in a private/incognito window where you are signed out. You can fill it in without requesting access. Google may offer sign-in to save a draft; this is optional. Check that you can submit while signed out. If the account blocks public responses, change its settings or choose another form.'],
  ['test-order','Send en prøve med navnet TEST, en ufølsom kontaktoplysning og antal for mindst én vare. Bekræftelsesteksten vises.','Submit a test named TEST, non-sensitive contact information and a quantity for at least one item. The confirmation message appears.'],
  ['test-sheet','Find TEST-rækken i Svar og i regnearket. Kontrollér varenavne, varianter og antal mod dit katalog.','Find the TEST row in Responses and the spreadsheet. Check product names, variants and quantities against your catalog.'],
  ['test-process','Kopiér prøveordren til Ordrebog. Beregn beløbet fra antal × dine aftalte priser. Prøv status “Bekræftet”, betaling “Afventer” og en note. Der sker ingen automatisk betaling, lagerreservation eller kundemail.','Copy the test order to Order book. Calculate the amount from quantities × your agreed prices. Try status “Confirmed”, payment “Pending” and a note. There is no automatic payment, stock reservation or customer email.']
 ]},
 {id:'export',title:['5. Opret dit Shop Site','5. Create your Shop Site'],intro:['Se kundesiden nedenfor. Den indeholder kun dit katalog, offentlige kontakt-/betalingsoplysninger og respondentlinket. Din arbejdswiki, afkrydsninger og private arkadresse følger ikke med.','Preview the customer site below. It contains only your catalog, public contact/payment details and responder link. Your working wiki, checkboxes and private sheet address are not included.'],checks:[
  ['preview-checked','Jeg har læst kundesiden og kontrolleret priser, billeder, kontakt, levering og eventuelle betalingsoplysninger. Eksterne billeder skal kunne ses uden login.','I have read the customer site and checked prices, images, contact, delivery and any payment details. External images must be viewable without signing in.'],
  ['export-saved','Jeg har hentet index.html til Funnel eller indlejringskoden til Google Sites. Jeg har også gemt arbejdswikien med TiddlyWikis Gem-knap.','I have downloaded index.html for Funnel or the embed code for Google Sites. I have also saved my working wiki using TiddlyWiki’s Save button.']
 ]},
 {id:'publish',title:['6. Del med kunder','6. Share with customers'],intro:['Vælg én udgivelsesvej. Du kan skifte senere og bruge samme katalog og formular. Google Sites gemmer den indlejrede udgave; Funnel viser udgaven fra din tændte computer.','Choose one publishing route. You can switch later using the same catalog and form. Google Sites stores the embedded version; Funnel serves the version from your running computer.'],checks:[]},
 {id:'finish',title:['7. Åbn butikken — og hold den ajour','7. Open your shop — and keep it up to date'],intro:['Afkrydsning er din egen bekræftelse. Shop har ikke adgang til at kontrollere Google eller Funnel for dig. Del først linket, når hele kundens vej er prøvet.','A checkmark is your own confirmation. Shop cannot inspect Google or Funnel for you. Share the link after testing the complete customer journey.'],checks:[
  ['public-mobile','Åbn det offentliggjorte link på en telefon uden ejerlogin. Ved Funnel: brug mobildata uden Tailscale-forbindelse. Siden vises, billederne virker, og Bestil åbner den rigtige formular.','Open the published link on a phone without the owner’s login. For Funnel, use mobile data without a Tailscale connection. The page and images appear, and Order opens the correct form.'],
  ['public-order','Send en sidste TEST-bestilling fra den offentlige side. Find svaret i dit private ark, og markér testen som annulleret i Ordrebog.','Send a final TEST order from the public site. Find the response in your private sheet and mark the test cancelled in Order book.'],
  ['update-routine','Når varer eller priser ændres: ret kataloget og en eventuel formular, gennemfør prøven igen og udgiv en ny kundeside. I Google Sites: erstat indlejringskoden og klik Offentliggør (Publish). Ved Funnel: erstat index.html.','When products or prices change: update the catalog and any form, repeat the test and publish a new customer page. In Google Sites, replace the embed code and click Publish. For Funnel, replace index.html.'],
  ['daily-routine','Jeg ved, hvordan jeg åbner ordrearket, bekræfter en ordre, kontrollerer betaling og markerer udlevering. Jeg gemmer arbejdswikien efter ændringer.','I know how to open the order sheet, confirm an order, verify payment and mark delivery. I save my working wiki after changes.']
 ]}
];
exports.routes={sites:[
 ['sites-create','Åbn Google Sites, log ind, og vælg Tomt website. Navngiv sitet, fx “Min Shop”.','Open Google Sites, sign in and choose Blank. Name the site, for example “My Shop”.','https://sites.google.com/new'],
 ['sites-embed','I højre side vælger du Indsæt → Integrer → Integrer kode. Kopiér hele indlejringskoden fra trin 5 ind i feltet. Vælg Næste og Indsæt.','On the right choose Insert → Embed → Embed code. Paste the full embed code from step 5. Choose Next and Insert.','https://support.google.com/sites/answer/90569'],
 ['sites-size','Klik på indlejringen. Træk det blå håndtag på højre kant ud til sidens bredde. Træk det nederste håndtag ned, indtil både varer, bestillingsknap og sidefod har plads. Rul siden ned og træk igen, hvis det er nødvendigt. Brug Forhåndsvisning og telefonvisningen. Hvis du bruger en formular, åbnes den i en ny fane.','Click the embed. Drag the blue handle on its right edge to the page width. Drag the bottom handle down until the products, order button and footer fit. Scroll down and drag again if needed. Use Preview and the phone layout. If you use a form, it opens in a new tab.'],
 ['sites-publish','Klik Udgiv, vælg en adresse og udgiv. Kontrollér, at den offentliggjorte side kan ses af dine kunder. Brug Kopiér link til udgivet website øverst; linket kan ende på /start. Brug hele linket. Ved senere ændringer: gennemse forskellene og klik Offentliggør igen.','Click Publish, choose an address and publish. Check that your customers can view the published site. Use Copy published site link at the top; the link may end in /start. Use the entire link. For later changes, review the differences and click Publish again.','https://support.google.com/sites/answer/6372880'],
 ['sites-check','Åbn adressen i et privat vindue. Prøv kundesiden og en eventuel Bestil-knap fra den indlejrede Shop. Hvis din konto begrænser offentlig deling, løs adgangsproblemet før du deler linket.','Open the address in a private window. Try the customer page and any Order button in the embedded Shop. If your account restricts public sharing, resolve access before sharing the link.']
],funnel:[
 ['funnel-install','Installér Node.js LTS og Tailscale på den computer, der skal vise butikken. Log ind i Tailscale. Computeren skal være tændt og online, når kunder besøger butikken.','Install Node.js LTS and Tailscale on the computer that will serve the shop. Sign into Tailscale. The computer must be on and online when customers visit.','https://nodejs.org/en/download'],
 ['funnel-folder','Opret mappen Shop-public. Læg kun index.html fra trin 5 og shop-server.cjs fra knappen nedenfor i den. Din arbejdswiki og ordreark hører ikke til her.','Create a Shop-public folder. Put only index.html from step 5 and shop-server.cjs from the button below in it. Your working wiki and order sheet do not belong here.'],
 ['funnel-local','Åbn Terminal (Mac/Linux) eller PowerShell (Windows). Skriv cd efterfulgt af et mellemrum, træk Shop-public-mappen ind, og tryk Enter. Kør derefter: node shop-server.cjs. Åbn http://127.0.0.1:8787 og kontrollér kundesiden. Lad vinduet stå åbent.','Open Terminal (Mac/Linux) or PowerShell (Windows). Type cd followed by a space, drag in the Shop-public folder, then press Enter. Run: node shop-server.cjs. Open http://127.0.0.1:8787 and check the customer page. Leave the window open.'],
 ['funnel-ports','Kontrollér først: tailscale serve status. HTTPS-porten 443 skal være ledig. Er den optaget, kan du bruge en ledig port 8443 eller 10000 med --https=8443 eller --https=10000. Er alle optaget, skal du stoppe her og aftale en ændring med ejeren. Genbrug aldrig en privat tjenestes port eller sti til offentlig Funnel.','First run: tailscale serve status. HTTPS port 443 must be unused. If occupied, use an unused port 8443 or 10000 with --https=8443 or --https=10000. If all are occupied, stop here and agree a change with the owner. Never reuse a private service’s port or path for public Funnel.','https://tailscale.com/docs/reference/tailscale-cli/funnel'],
 ['funnel-enable','Åbn et nyt terminalvindue. Hvis 443 er ledig, kør: tailscale funnel --https=443 8787. Følg Tailscales godkendelseslink, hvis det vises. Det kan kræve din Tailscale-administrator. Funnel forbinder den valgte offentlige HTTPS-port med kundesiden på lokal port 8787; brug aldrig din redigerbare wikis port.','Open another terminal window. If 443 is unused, run: tailscale funnel --https=443 8787. Follow Tailscale’s approval link if shown. Your Tailscale administrator may be needed. Funnel connects the selected public HTTPS port to the customer page on local port 8787; never use your editable wiki’s port.','https://tailscale.com/docs/features/tailscale-funnel'],
 ['funnel-link','Kopiér https-adressen, som terminalen viser under “Available on the internet”. Kunder behøver ikke Tailscale. Lad begge terminalvinduer og computeren køre. Funnel har båndbreddegrænser og er ikke en garanti for konstant oppetid.','Copy the https address displayed under “Available on the internet”. Customers do not need Tailscale. Keep both terminal windows and the computer running. Funnel has bandwidth limits and does not guarantee constant uptime.'],
 ['funnel-test','Åbn hele https-linket i et privat browservindue. Kontrollér kataloget og Bestil-knappen. Send kun en tydeligt mærket TEST-bestilling og kontrollér modtagelsen i dit ordreark.','Open the complete https link in a private browser window. Check the catalog and Order button. Submit only a clearly marked TEST order and check receipt in your order sheet.'],
 ['funnel-mobile','Prøv også det fulde link og Bestil-knappen fra en telefon på mobildata med Tailscale slået fra. Kontrollér, at teksten kan læses og alle varer kan ses.','Also test the complete link and Order button on a phone using mobile data with Tailscale turned off. Check that text is readable and all products are visible.'],
 ['funnel-stop','Prøv at stoppe udgivelsen med Ctrl+C i Funnel-vinduet og kontrollér, at det offentlige link ikke længere virker. Start igen med samme kommando. Ctrl+C i servervinduet stopper også kundesiden. Ved genstart skal begge kommandoer startes igen.','Try stopping publication with Ctrl+C in the Funnel window and check the public link no longer works. Restart with the same command. Ctrl+C in the server window also stops the customer page. After restarting the computer, start both commands again.']
]};
exports.troubleshooting=[
 ['Google beder kunden om login','Google asks customers to sign in','Kontrollér respondentadgang, Begræns til ét svar, verificeret mail og filupload. Skole-/arbejdskonti kan have faste begrænsninger. Test i privat vindue.','Check responder access, Limit to 1 response, verified email and file uploads. School/work accounts may impose restrictions. Test in a private window.'],
 ['Svar mangler i arket','Response missing from the sheet','Se først Svar i den rigtige formular. Kontrollér derefter svardestinationen. Genbrug ikke et gammelt respondentlink efter at have kopieret formularen.','First check Responses in the correct form. Then check its response destination. Do not reuse an old responder link after copying the form.'],
 ['Funnel-kommandoen findes ikke','Funnel command not found','Åbn Tailscale og kontrollér installationen af kommandolinjeværktøjet. På Mac kan stien være /Applications/Tailscale.app/Contents/MacOS/Tailscale; brug den fulde sti i stedet for tailscale. Se Tailscales installationsvejledning.','Open Tailscale and check command-line installation. On Mac the path may be /Applications/Tailscale.app/Contents/MacOS/Tailscale; use the full path instead of tailscale. See Tailscale’s installation guide.'],
 ['Shop er ændret, men kunder ser det gamle','Shop changed, but customers see the old version','Google Sites opdaterer ikke sig selv fra din wiki. Eksportér ny kode, erstat indlejringen og udgiv igen. Ved Funnel erstattes index.html i den samme mappe. Genindlæs kundesiden.','Google Sites does not update itself from your wiki. Export new code, replace the embed and publish again. For Funnel replace index.html in the same folder. Reload the customer page.']
];
exports.externalChecks=[
 ['external-created','Jeg har oprettet en formular hos min valgte tjeneste med navn, kontakt, antal pr. vare og en valgfri besked.','I have created a form with my chosen service containing name, contact, quantity per product and an optional message.'],
 ['external-tested','Jeg har åbnet linket uden ejerlogin, sendt en TEST-bestilling og kontrolleret, at jeg modtager den hos min valgte tjeneste.','I have opened the link without the owner’s login, sent a TEST order and verified receipt with my chosen service.']
];
"},"$:/plugins/huwiki/shop/widget.js":{"title":"$:/plugins/huwiki/shop/widget.js","type":"application/javascript","module-type":"widget","text":""use strict";
var Widget=require('$:/core/modules/widgets/widget.js').widget,model=require('$:/plugins/huwiki/shop/model.js'),guide=require('$:/plugins/huwiki/shop/guide.js');
var DATA='$:/plugins/huwiki/shop/data';
function Shop(tree,options){this.initialise(tree,options);}
Shop.prototype=new Widget();
Shop.prototype.lang=function(){return /(?:^|\/)da-DK$/.test(this.wiki.getTiddlerText('$:/language',''))?'da':'en';};
Shop.prototype.render=function(parent,nextSibling){
 this.parentDomNode=parent;this.computeAttributes();this.execute();
 this.language=this.lang();this.en=this.language==='en';this.data=this.wiki.getTiddlerData(DATA,null)||{draft:model.fromTemplate('fest',this.language),checks:{},step:0,route:'sites',sheetUrl:''};
